all_files = ['survey-2024-q1.csv', 'survey-2024-q2.csv', 'survey-2024-q3.csv', 'survey-2024-q4.csv', 'survey-2025-q1.csv', 'survey-2025-q2.csv', 'survey-2025-q3.csv', 'survey-2025-q4.csv']
cleaned = {'survey-2024-q1.csv', 'survey-2024-q3.csv', 'survey-2025-q1.csv', 'survey-2025-q2.csv'}
left = [f for f in all_files if f not in cleaned]
print(f'{len(all_files)} files total, {len(cleaned)} cleaned, {len(left)} remaining')
for f in left:
    print(' -', f)

tests = {'test_int': True, 'test_float': True, 'test_str': True, 'test_bool': True, 'test_null': True, 'test_list': True, 'test_dict': True, 'test_nested': True, 'test_unicode': True, 'test_escape': True, 'test_number_exp': True, 'test_empty': True, 'test_ws': True, 'test_dup_keys': True, 'test_deep': True, 'test_big': True, 'test_date': False, 'test_tz': True}
passed = sum(tests.values())
print(f'{passed}/{len(tests)} tests passing')
for name, ok in tests.items():
    if not ok:
        print(f'FAILING: {name}')

config = {'max_connections': 500, 'timeout_seconds': 30, 'retry_limit': 3, 'log_level': 'info'}
errors = []
if config['max_connections'] > 200:
    errors.append('max_connections 500 exceeds the database pool ceiling of 200')
if config['timeout_seconds'] < config['retry_limit'] * 5:
    errors.append('timeout_seconds too small for retry_limit')
print('VALID' if not errors else 'INVALID:')
for e in errors:
    print(' -', e)

